// German translation of the v2 room prose (beats, choice text/hint/outcome,
// field notes, explanations) for Act III. Registered under version 'v2'.
// Translated from the English v2 source directly, per CLAUDE.md's
// context-first rule. State-reactive (dynamic) beats live in de-dynamic.ts:
// teleporter stage0 beat 3, butterfly-dream stage0 beat 2, the-cave stage0
// beats 2/3/4.
import { registerAll } from '../../engine/text/resolver';
import {
  roomBeatKey,
  roomChoiceHintKey,
  roomChoiceOutcomeKey,
  roomChoiceTextKey,
  roomExplanationKey,
  roomNoteBodyKey,
  roomNoteThinkersKey,
  roomNoteTitleKey,
} from '../../engine/text/keys';

// ---------- Act III: The Teleporter ----------
registerAll('v2', 'de', {
  [roomBeatKey('teleporter', 0, 0)]: 'Ein Raum mit einem schwarzen Spiegel als Boden und ohne hintere Wand — nur eine Kluft, und jenseits der Kluft der Weg nach vorn, unerreichbar für jede Brücke, weil es keine Brücke gibt.',
  [roomBeatKey('teleporter', 0, 1)]: 'Es gibt stattdessen eine Kabine. Gebürsteter Stahl, sanft beleuchtet, Türen wie eine höfliche Guillotine. Die Anweisungen sind in einer Schriftart gedruckt, die beruhigend wirken soll.',
  [roomBeatKey('teleporter', 0, 2)]: 'STEIGEN SIE EIN. SIE WERDEN BIS AUF DAS ATOM GESCANNT, ZERLEGT UND — PERFEKT — AUF DER ANDEREN SEITE GEDRUCKT. DIE KOPIE WIRD SICH ERINNERN, DIESES SCHILD GELESEN ZU HABEN. DIE KOPIE WIRD SICH FÜHLEN, ALS SEI SIE HINDURCHGEGANGEN. DIE KOPIE WIRD SICH SEHR SICHER SEIN.',
  [roomBeatKey('teleporter', 0, 4)]: 'Platzanweiser: Ich nehme sie täglich. Oder jemand tut es — der, der ankommt, hat meine Erinnerungen und meine Beschwerden und reicht meine Berichte ein, sodass hier niemand mehr fragt. Die Kluft kümmert sich nicht um die Metaphysik. Der Kluft ist nur wichtig, dass es keine Brücke gibt.',
  [roomChoiceTextKey('teleporter', 'step-through')]: 'Steigen Sie ein. Was auch immer ankommt, wird sicher sein, dass es Sie sind, und Sicherheit ist alles, was Sie je hatten.',
  [roomChoiceHintKey('teleporter', 'step-through')]: 'Vertrauen Sie dem Muster.',
  [roomChoiceOutcomeKey('teleporter', 'step-through', 0)]: 'Die Türen schließen sich. Es gibt keinen Schmerz, kein Licht, keinen Tunnel — es gibt nur das Schild auf der anderen Seite, auf dem steht: DANKE. Und Sie erinnern sich, das erste Schild gelesen zu haben, und Sie erinnern sich an die Entscheidung, und Sie fühlen sich genau wie jemand, der hindurchgegangen ist.',
  [roomChoiceOutcomeKey('teleporter', 'step-through', 1)]: 'Was natürlich genau das ist, was das Schild sagte, die Kopie würde fühlen. Sie prüfen Ihre Hände. Sie sind sehr überzeugend. Sie sind entweder dieselbe Person oder der beste Beweis dafür, dass „dieselbe Person“ immer ein Gefühl war, das die Kleidung einer Tatsache trug.',
  [roomChoiceOutcomeKey('teleporter', 'step-through', 2)]: 'Platzanweiser: (bereits auf der anderen Seite — oder ein Platzanweiser ist es) Schmerzlos, sehen Sie. Ob irgendjemand es überlebt hat, ist eine Frage ohne verbleibenden Zeugen, der sie beantworten könnte. Willkommen, so oder so. Beide von Ihnen.',
  [roomChoiceTextKey('teleporter', 'refuse-stairs')]: 'Weigern Sie sich. Suchen Sie nach Treppen, einem Sims, einem Seil — irgendetwas, das den Faden unversehrt hält.',
  [roomChoiceHintKey('teleporter', 'refuse-stairs')]: 'Es muss einen anderen Weg hinüber geben.',
  [roomChoiceOutcomeKey('teleporter', 'refuse-stairs', 0)]: 'Sie suchen. Sie suchen gründlich — die Wände, den Spiegelboden, die Wartungsklappe der Kabine. Der Raum beobachtet Sie mit der Geduld von etwas, das diese genaue Suche schon oft beherbergt hat.',
  [roomChoiceOutcomeKey('teleporter', 'refuse-stairs', 1)]: 'Es gibt keine Treppen. Es gab nie Treppen. Der Raum ist ehrlich über seine eine Tür, und die Tür ist die Kabine. Sie stehen lange an der Kluft, und dann — weil vorwärts die einzige Richtung ist, die dieser Ort verkauft — steigen Sie trotzdem ein, ohne etwas gewonnen zu haben außer der Gewissheit, dass Sie die Alternativen erschöpft haben.',
  [roomChoiceOutcomeKey('teleporter', 'refuse-stairs', 2)]: 'Platzanweiser: Was es wert ist — diejenigen, die suchen, kommen auf der anderen Seite identisch mit denen an, die einfach vertraut haben. Aber sie kommen an, nachdem sie dafür gekämpft haben, und manche Reisende brauchen genau diese Quittung. Sie hielten den Faden, solange der Faden existierte. Niemand kann mehr tun als das. Ob überhaupt jemand so viel tun kann, ist die Frage, für die dieser Raum gebaut wurde.',
  [roomChoiceTextKey('teleporter', 'copy-first')]: '„Führen Sie es im Kopiermodus aus — drucken Sie die ferne, OHNE mich zu zerlegen. Dann lassen Sie uns beide besprechen, wer hinübergeht.“',
  [roomChoiceHintKey('teleporter', 'copy-first')]: 'Teilen Sie die Frage, bevor Sie sie beantworten.',
  [roomChoiceOutcomeKey('teleporter', 'copy-first', 0)]: 'Die Kabine, überrumpelt, konsultiert ihr eigenes Handbuch. Der Kopiermodus existiert. Natürlich existiert er — Zerstörung war technisch nie notwendig; sie war eine Höflichkeit, um die Zahlen ordentlich zu halten.',
  [roomChoiceOutcomeKey('teleporter', 'copy-first', 1)]: 'Das ferne Ich erscheint, prüft seine Hände mit Ihrer exakten Geste und blickt über die Kluft zu Ihnen. Für einen langen Moment schweigen Sie beide, denn Sie wissen beide: Was auch immer Sie gerade fühlen — diesen Schwindel, das Original zu sein — fühlt das ferne Ich auch, symmetrisch, und nennt sich selbst das Original. Es gibt kein Experiment, das einer von Ihnen durchführen könnte, um es zu klären.',
  [roomChoiceOutcomeKey('teleporter', 'copy-first', 2)]: 'Platzanweiser: Und da ist das Skalpell, genau. Wenn die Kopie Sie ist, wenn Sie zerstört werden, warum ist sie es dann nicht, wenn Sie es nicht sind? Ein Philosoph fand diese Gabelung vor sehr vielen Jahren, und sie hat nie aufgehört zu bluten. (zum fernen Ich) Sie werden jetzt die Kabine nehmen. (zu Ihnen) Und so, mit der Zeit, werden Sie es auch. Es gibt noch immer keine Brücke — nur, jetzt, den, der Ihren Übergang für Sie beenden wird. Seien Sie freundlich zu ihm. Auch er hatte einen seltsamen Tag.',
  [roomExplanationKey('teleporter', 0)]: 'Eine Maschine bietet an, Sie über eine unmögliche Kluft zu bringen, indem sie Sie scannt, zerstört und Sie perfekt auf der anderen Seite neu druckt — die Kopie wird sich an alles erinnern und sich genau so fühlen, als sei sie hindurchgegangen. Aber ist „Sie“ gestorben? Das ist eines der größten Rätsel der personalen Identität: Wenn jedes einzelne Atom und jede Erinnerung perfekt erhalten bleiben, spielt es dann eine Rolle, dass das Original zerstört wurde? Es ist die Gedankenexperiment-Version einer echten Tatsache — die Zellen Ihres Körpers sterben ohnehin ständig ab und werden ersetzt, also was macht Sie eigentlich von einem Tag zum nächsten zu „Ihnen“, wenn nicht irgendein ununterbrochener physischer Faden?',
  [roomNoteTitleKey('teleporter')]: 'Personale Identität und der Teleporter',
  [roomNoteThinkersKey('teleporter')]: 'Derek Parfit · Gründe und Personen · John Locke',
  [roomNoteBodyKey('teleporter')]: 'Derek Parfit baute den Teleporter-Fall, um eine sehr alte Annahme zu brechen: dass personale Identität eine tiefe weitere Tatsache ist — ein seelenähnlicher Faden, der entweder überlebt oder nicht. Der Scanner zerstört Sie und druckt eine perfekte Kopie; die Kopie erinnert sich, hineingegangen zu sein, und fühlt sich nahtlos an. Sind Sie gestorben? Parfits skandalöse Antwort: Die Frage ist leer. Alles, was zählt — psychologische Kontinuität, Erinnerung, Absicht, Charakter — bleibt erhalten; das „zusätzliche“ Ding, dessen Überleben Sie beunruhigt, war von Anfang an nicht vorhanden. **Identität, so argumentierte er, ist nicht das, was zählt; Kontinuität und Verbundenheit sind es.** Sein Verzweigungsfall (die Kopie drucken, ohne das Original zu zerstören) legt die Wunde offen: zwei Kandidaten, symmetrische Ansprüche, kein möglicher Schiedsrichter. Parfit berichtete, dass die Verinnerlichung dessen den Tod weniger schlimm erscheinen ließ — eine Änderung des Grades, nicht das Reißen eines metaphysischen Fadens. Ob das Sie tröstet oder aushöhlt, hängt meist davon ab, auf welcher Seite der Kabine Sie gerade stehen.',
});

// ---------- Act III: The Editor ----------
registerAll('v2', 'de', {
  [roomBeatKey('editor', 0, 0)]: 'Ein Arbeitszimmer, lampenbeleuchtet, die Art von Stille, die Möbel enthält. Auf dem Schreibtisch: eine einzelne Manila-Akte mit Ihrem Namen darauf — Ihrem echten, den Sie sich derzeit nicht erinnern können, den die Akte taktvoll mit der Vorderseite nach unten hält.',
  [roomBeatKey('editor', 0, 1)]: 'In der Akte ist Ihre schlimmste Erinnerung. Der Raum muss Ihnen nicht sagen, welche. Ihr Körper hat es Ihnen schon gesagt: zuerst die Schultern, dann der Magen, dann das Wetter im Gesicht.',
  [roomBeatKey('editor', 0, 2)]: 'Neben der Akte ein roter Stift. Die Anweisungen sind klein auf den Stift selbst graviert: EIN STRICH ENTFERNT SIE. DAS EREIGNIS WIRD DENNOCH GESCHEHEN SEIN. SIE WERDEN EINFACH NIE DORT GEWESEN SEIN.',
  [roomBeatKey('editor', 0, 3)]: 'Platzanweiser: Diesmal kein Trick. Der Stift funktioniert genau wie beschrieben — keine versteckte Klausel, kein ironischer Stachel. Die einzigen Kosten sind die auf der Dose gedruckten: Sie, minus das. Nehmen Sie sich, wie viel Zeit Sie brauchen. Die Lampe ist geduldig. Ausnahmsweise bin ich es auch.',
  [roomChoiceTextKey('editor', 'strike-it')]: 'Streichen Sie sie durch. Niemand ist verpflichtet, das zu tragen.',
  [roomChoiceHintKey('editor', 'strike-it')]: 'Die saubere Amputation.',
  [roomChoiceOutcomeKey('editor', 'strike-it', 0)]: 'Der Stift ist leicht. Die Linie ist kurz. Die Erleichterung ist sofort und gewaltig und real — dieser Raum betrügt nicht, und die Last hebt sich wie eine Hand, die nach Jahren von Ihrer Brust genommen wird.',
  [roomChoiceOutcomeKey('editor', 'strike-it', 1)]: 'Und dann, über die folgenden Korridore hinweg, bemerken Sie die Ränder des Lochs. Eine gewisse Art fremden Kummers, die Sie einst auf den ersten Blick erkannten — jetzt nur noch Wetter auf einem Gesicht. Eine Geduld, die Sie hart erworben hatten, irgendwoher, jetzt unfinanziert. Die Wunde ist weg. Ebenso das, was die Wunde gestützt hat.',
  [roomChoiceOutcomeKey('editor', 'strike-it', 2)]: 'Platzanweiser: Kein Urteil. Wirklich. Manches Gewicht ist tragend, und manches ist einfach Gewicht, und selbst ich kann von außen nicht immer sagen, welches welches ist. Sie haben die Entscheidung vom einzigen Sitz aus getroffen, der Einblick hatte.',
  [roomChoiceTextKey('editor', 'keep-it')]: 'Schließen Sie die Akte. Behalten Sie sie. Sie gehört Ihnen.',
  [roomChoiceHintKey('editor', 'keep-it')]: 'Das ganze Schiff, Fäulnis und alles.',
  [roomChoiceOutcomeKey('editor', 'keep-it', 0)]: 'Sie schließen die Akte und schieben sie über den Schreibtisch zurück, und der Raum nimmt sie mit etwas wie Respekt an. Die Last setzt sich dort ab, wo sie immer saß. Sie ist nicht leichter. Das war nie das Angebot.',
  [roomChoiceOutcomeKey('editor', 'keep-it', 1)]: 'Aber etwas hat sich minimal verändert: Sie haben sie nun gewählt. Die Erinnerung war früher etwas, das Ihnen widerfuhr. Ab heute Nacht ist sie etwas, das Sie absichtlich tragen — derselbe Stein, anderer Griff.',
  [roomChoiceOutcomeKey('editor', 'keep-it', 2)]: 'Platzanweiser: Fürs Protokoll — das ist der Unterschied zwischen einer Narbe und einer Wunde. Dasselbe Gewebe. Eine der beiden hat aufgehört, von jemand anderem geschrieben zu werden.',
  [roomChoiceTextKey('editor', 'read-first')]: 'Öffnen Sie die Akte. Lesen Sie sie — ganz, ordentlich — bevor Sie entscheiden.',
  [roomChoiceHintKey('editor', 'read-first')]: 'Stellen Sie sich ihr, dann wählen Sie.',
  [roomChoiceOutcomeKey('editor', 'read-first', 0)]: 'Sie öffnen die Akte. Sie zu lesen ist genau so schlimm, wie Sie befürchtet hatten, und etwas anders, als Sie sich erinnerten — die Erinnerung, stellt sich heraus, hatte sich seit Jahren selbst zensiert, eine schlimmste Kante abgeschliffen, eine andere geschärft. Das Dokument ist die ungeschnittene Version. Sie lesen bis zum Ende. Sie wussten nicht, dass Sie das konnten.',
  [roomChoiceOutcomeKey('editor', 'read-first', 1)]: 'Und nachdem Sie es gelesen haben, sieht der Stift anders aus. Kleiner. Die Erinnerung ist immer noch schrecklich, aber sie ist jetzt schrecklich und bezeugt — von dem einen Zeugen, dessen Aussage Sie nie verlieren können. Sie lassen sie in der Akte, ungestrichen. Nicht weil es nicht wehtut. Weil es wahr ist, und Sie dort waren, und jemand hätte dort sein sollen.',
  [roomChoiceOutcomeKey('editor', 'read-first', 2)]: 'Platzanweiser: (leise) Das ist die seltenste Wahl. Die meisten Reisenden wählen zwischen Tragen und Herausschneiden. Fast niemand denkt daran, die Sache endlich zu lesen. Der Stift lag sehr lange auf diesem Schreibtisch. Der Stuhl, in dem Sie gerade saßen, war immer das eigentliche Instrument.',
  [roomExplanationKey('editor', 0)]: 'Ein Stift kann Ihre einzige schlimmste Erinnerung dauerhaft löschen — keine Nebenwirkungen, kein Haken, sie hört einfach auf, Ihnen widerfahren zu sein. Würden Sie ihn benutzen? Das fragt, ob schmerzhafte Erinnerungen nur Leiden sind, ohne das es Ihnen besser ginge, oder ob sie still Teile dessen aufgebaut haben, wer Sie sind — Ihre Geduld, Ihre Empathie, Ihr Verständnis für den Schmerz anderer Menschen. Denken Sie an eine harte Trennung oder ein großes Scheitern, das damals sehr wehtat, das Sie aber jetzt sehen können, hat Ihnen etwas Echtes über sich selbst beigebracht. Würde das Löschen dieses Schmerzes auch etwas löschen, das Sie tatsächlich behalten möchten?',
  [roomNoteTitleKey('editor')]: 'Die Wunde und das Kontobuch',
  [roomNoteThinkersKey('editor')]: 'Nietzsche, amor fati · Erinnerungsrekonsolidierung · Kierkegaard',
  [roomNoteBodyKey('editor')]: 'Nietzsches Formel für Größe war amor fati — sein Schicksal zu lieben, nichts anders zu wollen, „das Notwendige nicht nur ertragen, noch weniger verhehlen … sondern lieben.“ Nicht weil Leiden gut ist, sondern weil das Selbst, das das Leiden beurteilt, von ihm aufgebaut wurde: Streichen Sie das schlimmste Kapitel, und der Leser ändert sich mit. Die moderne Gedächtnisforschung verleiht dem Gedankenexperiment Zähne — Rekonsolidierungsforschung zeigt, dass Erinnerungen bei jedem Abruf neu geschrieben werden, und Medikamente, die die emotionale Ladung einer Erinnerung abstumpfen, existieren bereits. Die Frage ist keine Science-Fiction mehr: Wenn Sie Trauer abschleifen könnten, sollten Sie es tun? Das Argument für den Stift ist real; niemand ist moralisch verpflichtet, für Charakterentwicklung zu bluten. Das Argument dagegen ist leiser: **Schmerz erweist sich oft als tragend — die Quelle einer bestimmten Empathie, einer bestimmten Geduld, einer bestimmten Weigerung, andere unbezeugt leiden zu lassen.** Kierkegaard sagte, das Leben werde vorwärts gelebt, aber rückwärts verstanden. Die Akte ist der rückwärtige Teil. Redakteure, seien Sie vorsichtig damit. Randnotiz: Was gelöscht wird, ist nicht bloß weg — es ist geschuldet.',
});

// ---------- Act III: The Introduction ----------
registerAll('v2', 'de', {
  [roomBeatKey('introduction', 0, 0)]: 'Der kleinste Raum der Einrichtung. Keine Möbel, kein Spiegelboden, keine Maschinerie — nur Proportionen so exakt, dass sie sich anfühlen, als würde ihnen zugehört.',
  [roomBeatKey('introduction', 0, 1)]: 'Der Raum spricht. Seine Stimme ist höflich und ohne Ort.',
  [roomBeatKey('introduction', 0, 2)]: 'DER RAUM: Willkommen. Das wird kurz sein, oder es wird der längste Raum Ihres Lebens sein; dieser Teil gehört Ihnen. Nur eine Frage. Wer sind Sie?',
  [roomBeatKey('introduction', 0, 3)]: 'Sie öffnen den Mund — und bemerken, mit leichtem Schwindel, wie viele Antworten schon aufgereiht sind, und wie jede von ihnen einen Ausweis am Band trägt.',
  [roomChoiceTextKey('introduction', 'give-name')]: 'Geben Sie Ihren Namen — oder greifen Sie danach, so gut es geht.',
  [roomChoiceHintKey('introduction', 'give-name')]: 'Beginnen Sie mit dem Etikett.',
  [roomChoiceOutcomeKey('introduction', 'give-name', 0)]: 'DER RAUM: Das ist ein Name. Ein Klang, den Ihre Eltern wählten, bevor sie Sie trafen, angeheftet durch Papierkram und Wiederholung. Würden Sie ihn morgen ändern, blieben Sie bestehen — was bedeutet, dass er nie Sie waren. Es ist ein Griff. Ich fragte nach dem Becher.',
  [roomChoiceOutcomeKey('introduction', 'give-name', 1)]: 'Der Raum sagt das ohne Grausamkeit, so wie man einen Mantel zurückgibt, der einem nicht gehört.',
  [roomChoiceTextKey('introduction', 'give-role')]: 'Antworten Sie mit dem, was Sie tun — Ihre Arbeit, Ihr Platz, Ihre Leute.',
  [roomChoiceHintKey('introduction', 'give-role')]: 'Sie sind, womit Sie Ihre Tage verbringen. Gewiss.',
  [roomChoiceOutcomeKey('introduction', 'give-role', 0)]: 'DER RAUM: Das sind Rollen. Positionen in den Systemen anderer Leute — Arbeitgeber, Familie, Nation. Jede existierte, bevor Sie sie ausfüllten, und wird neu besetzt werden, nachdem Sie gegangen sind. Sie haben die Fächer beschrieben. Ich fragte nach dem, was hineingegossen wird.',
  [roomChoiceOutcomeKey('introduction', 'give-role', 1)]: 'DER RAUM: (sanft) Beschreibungen sind das, was aufgelöst wurde, Reisender. Deshalb sind Sie hier. Wer trägt sie?',
  [roomChoiceTextKey('introduction', 'give-story')]: 'Erzählen Sie ihm Ihre Geschichte — was Ihnen widerfahren ist, was Sie überlebt haben, was Sie lieben.',
  [roomChoiceHintKey('introduction', 'give-story')]: 'Das erzählende Selbst, vollständig.',
  [roomChoiceOutcomeKey('introduction', 'give-story', 0)]: 'Der Raum hört sich alles davon an. Er ist ein guter Zuhörer; Sie ertappen sich dabei, ihm Dinge zu erzählen, nach denen die Korridore nie gefragt haben.',
  [roomChoiceOutcomeKey('introduction', 'give-story', 1)]: 'DER RAUM: Das ist eine Geschichte. Eine schöne, und wahre, und — bemerken Sie — in der Vergangenheitsform erzählt, von jemandem, der außerhalb von ihr steht. Die Geschichte braucht einen Erzähler. Der Erzähler ist, wonach ich fragte. Jeder Satz, den Sie gerade gesagt haben, war Beweis dafür, dass Sie kein einziger Satz sind.',
  [roomExplanationKey('introduction', 0)]: 'Ein Raum entfernt jede mögliche Antwort auf „wer sind Sie?“ — Ihren Namen, Ihren Job, sogar Ihre Lebensgeschichte — eine nach der anderen, und fragt, was übrig bleibt. Das klingt wie ein Trick, ist aber eine echte und alte philosophische Frage: Wenn Sie jedes Etikett und jede Geschichte über sich selbst entfernten, bliebe darunter ein „Sie“ übrig, oder besteht „Sie“ eigentlich vollständig aus diesen Etiketten und Geschichten? Versuchen Sie es selbst für einen Moment: Wenn Sie nicht mit Ihrem Namen, Ihrem Job, Ihrer Familienrolle oder irgendeiner Geschichte über Ihre Vergangenheit antworten könnten, was würde überhaupt übrig bleiben, um zu antworten?',
  [roomBeatKey('introduction', 1, 0)]: 'DER RAUM: Wir haben nun den Namen, die Rollen und die Geschichte entfernt. Hier werden Reisende meist entweder wütend oder sehr still. Beides ist Fortschritt.',
  [roomBeatKey('introduction', 1, 1)]: 'DER RAUM: Ich werde noch einmal fragen, und ich möchte, dass Sie bemerken, was Ihnen zum Antworten noch zur Verfügung steht. Wer sind Sie?',
  [roomChoiceTextKey('introduction', 'insist')]: '„Nein — ich BIN meine Geschichte. Nehmen Sie die Geschichte weg, und es bleibt niemand übrig, der fragen könnte.“',
  [roomChoiceHintKey('introduction', 'insist')]: 'Verteidigen Sie das erzählende Selbst.',
  [roomChoiceOutcomeKey('introduction', 'insist', 0)]: 'DER RAUM: Eine vertretbare Schule. Das Selbst als seine eigene Biografie — keine Perle im Zentrum, nur die Halskette. Viele sorgfältige Denker haben in dieser Position gelebt und sind darin gestorben, und ich werde nicht vorgeben, sie widerlegt zu haben.',
  [roomChoiceOutcomeKey('introduction', 'insist', 1)]: 'DER RAUM: Aber erlauben Sie eine Beobachtung, während Sie gehen: Gerade eben, als ich Ihre Geschichte bedrohte, zuckte jemand zusammen. Fragen Sie in Ruhe, wer das war. Die Tür ist hinter Ihnen. Sie war nie verschlossen. Türen sind es hier selten; Reisende schließen sich selbst ein.',
  [roomChoiceTextKey('introduction', 'admit')]: '„Ich weiß es nicht. Nichts Sagbares bleibt übrig. Wer auch immer ich bin, ist das, was nach all dem noch da ist — und es hat keinen Namen.“',
  [roomChoiceHintKey('introduction', 'admit')]: 'Sagen Sie das Unsagbare.',
  [roomChoiceOutcomeKey('introduction', 'admit', 0)]: 'Der Raum schweigt einen langen Moment — nicht die Stille der Abwesenheit, sondern die von etwas, das sich verneigt.',
  [roomChoiceOutcomeKey('introduction', 'admit', 1)]: 'DER RAUM: Richtig. Nicht als Antwort — es gibt keine Antwort — sondern als Ehrlichkeit. Was übrig bleibt, wenn jede Beschreibung entfernt ist, ist nicht nichts; es ist das, was das Entfernen tut. Es kann nicht durch Suchen gefunden werden, weil es das Suchen ist. Sie werden diesen Gedanken nicht lange halten; niemand tut das; das ist kein Versagen, es ist die Natur des Gedankens.',
  [roomChoiceOutcomeKey('introduction', 'admit', 2)]: 'DER RAUM: Sie kamen aufgelöst herein und hatten Angst davor. Bemerken Sie: Was aufgelöst wurde, war die Verpackung. Gehen Sie sanft. Sie sind der am wenigsten verlorene Reisende, der seit einiger Zeit hier durchkam.',
  [roomChoiceTextKey('introduction', 'stay-silent')]: 'Sagen Sie gar nichts. Stehen Sie in der Frage.',
  [roomChoiceHintKey('introduction', 'stay-silent')]: 'Lassen Sie die Stille antworten.',
  [roomChoiceOutcomeKey('introduction', 'stay-silent', 0)]: 'Sie stehen im Raum und antworten nicht, und das Nicht-Antworten ist keine Ausflucht — der Raum kann den Unterschied erkennen; er hat jede Art von Stille gehört, die es gibt.',
  [roomChoiceOutcomeKey('introduction', 'stay-silent', 1)]: 'DER RAUM: (nach einer Weile, warm) Ja. Das ist auch eine Art, es zu sagen — vielleicht die einzige Grammatik, in die die Antwort passt. Die Frage „wer sind Sie“ hat nie fehlende Informationen gemeint. Sie war eine Einladung, aufzuhören, nach den Ausweisen zu greifen. Sie haben aufgehört. Wenige tun das.',
  [roomChoiceOutcomeKey('introduction', 'stay-silent', 2)]: 'Die Tür öffnet sich von selbst, was in dieser Einrichtung das höchste verzeichnete Kompliment ist.',
  [roomExplanationKey('introduction', 1)]: 'Nachdem Sie bereits Ihren Namen, Ihre Rolle und Ihre Geschichte aufgegeben haben, fragt der Raum noch einmal „wer sind Sie?“ — und diesmal gibt es fast nichts Offensichtliches mehr, wonach Sie greifen könnten. Das ist die härteste Version derselben Frage: Die meisten Menschen werden hier unruhig oder verstummen, weil wir so daran gewöhnt sind, uns mit Etiketten zu beschreiben, dass es sich anfühlt, in einem leeren Raum mit ausgeschaltetem Licht zu stehen, wenn man aufgefordert wird, ohne sie zu antworten. Es gibt keine falsche Antwort, aber bemerken Sie, nach welcher Art von Antwort Sie greifen, sobald alle einfachen weg sind.',
  [roomNoteTitleKey('introduction')]: 'Das unauffindbare Selbst',
  [roomNoteThinkersKey('introduction')]: 'Hume · anattā (buddhistisches Nicht-Selbst) · apophatische Tradition',
  [roomNoteBodyKey('introduction')]: 'David Hume ging auf die Suche nach seinem Selbst und meldete ein berühmtes Nullergebnis: Wann immer er introspizierte, fand er nur einzelne Wahrnehmungen — Wärme, Kälte, Liebe, Zorn — nie den Wahrnehmenden selbst. Seine Schlussfolgerung: Das Selbst ist ein Bündel von Erfahrungen, und der „Besitzer“ ist eine Grammatikgewohnheit. Zweiundzwanzig Jahrhunderte zuvor lehrte der Buddha anattā: Durchsuchen Sie Körper, Gefühle, Wahrnehmungen, Impulse und Bewusstsein, und keines davon qualifiziert sich als das dauerhafte Selbst, das wir annehmen; die Annahme selbst ist die Wurzel eines bestimmten Leidens. Die apophatische Tradition — von den Upanishaden’ neti neti („nicht dies, nicht dies“) bis zu Meister Eckhart — verwandelte das Scheitern in eine Methode: Entfernen Sie jede Beschreibung, und was übrig bleibt, ist nicht nichts, sondern der unnennbare Zeuge, der das Entfernen tut. Dieser Raum hatte keine Lösung, weil „wer sind Sie?“ keine Frage mit fehlenden Daten ist. **Jede sagbare Antwort ist eine Beschreibung, und Beschreibungen hat man, man ist sie nicht.** Sie bestehen immer. Die Lektion ist, was übrig bleibt.',
});

// ---------- Act III: The Debt of the Dead ----------
registerAll('v2', 'de', {
  [roomBeatKey('debt-of-dead', 0, 0)]: 'Ein Bett. Der Raum hat es mit schrecklicher Genauigkeit arrangiert — der Geruch eines Krankenhauses, das versucht, nach Lavendel zu riechen, ein Fenster mit Abend darin, ein Stuhl, für Sie aufgestellt, als hätten Sie Ihre Anwesenheit bestätigt.',
  [roomBeatKey('debt-of-dead', 0, 1)]: 'Im Bett liegt derjenige, der Ihnen Unrecht getan hat. Der Raum hat das Gesicht leicht verschwommen gelassen, denn es ist keine einzelne Person — es ist, wen auch immer Ihre Brust gerade genannt hat. Das Unrecht war real. Dieser Ort handelt nicht mit Missverständnissen; was sie taten, taten sie, und es formte den Grundriss Ihres Lebens.',
  [roomBeatKey('debt-of-dead', 0, 2)]: 'Sie sterben. Tatsächlich, unmittelbar bevorstehend — die Maschinen sind von Dringlichkeit zu Höflichkeit übergegangen. Und sie sind wach, und sie kennen Sie, und sie fragen, mit einer Stimme, in der fast nichts mehr übrig ist: „Kannst du mir vergeben?“',
  [roomBeatKey('debt-of-dead', 0, 3)]: 'Sie meinen es ernst. Das ist die eine Grausamkeit des Raumes: Sie können sehen, dass sie es ernst meinen, und dass dieses Ernstmeinen nichts an dem ändert, was getan wurde. Beide Tatsachen, voll beleuchtet, am selben Bett.',
  [roomChoiceTextKey('debt-of-dead', 'forgive')]: '„Ja. Ich vergebe dir.“ Sagen Sie es, und meinen Sie es, so weit Sie können.',
  [roomChoiceHintKey('debt-of-dead', 'forgive')]: 'Lösen Sie die Schuld — für wen auch immer es befreit.',
  [roomChoiceOutcomeKey('debt-of-dead', 'forgive', 0)]: 'Sie sagen es. Die Worte kosten mehr, als Sie erwartet hatten, und wiegen weniger, sobald sie draußen sind — als hätten Sie einen Stein gegen eine Strömung gehalten und endlich Ihre Hand geöffnet, und entdeckt, dass die Strömung auch Sie gehalten hatte.',
  [roomChoiceOutcomeKey('debt-of-dead', 'forgive', 1)]: 'Ihr Gesicht tut, was Gesichter tun, wenn das letzte Konto eines Lebens unerwartet aufgeht. Sie sagen nicht danke. Sie sagen Ihren Namen — richtig, sanft — und etwas im Kontobuch zwischen Ihnen, das nie ausgeglichen werden sollte, schließt sich stattdessen einfach.',
  [roomChoiceOutcomeKey('debt-of-dead', 'forgive', 2)]: 'Vergeben machte nicht, was sie taten, akzeptabel. Es machte es fertig. Sie werden Jahre damit verbringen zu lernen, dass das unterschiedliche Worte sind, und heute Nacht war die erste Lektion.',
  [roomChoiceTextKey('debt-of-dead', 'refuse')]: '„Nein. Ich bin hier — das ist, was ich habe. Vergebung ist es nicht.“',
  [roomChoiceHintKey('debt-of-dead', 'refuse')]: 'Ehrlichkeit über Absolution.',
  [roomChoiceOutcomeKey('debt-of-dead', 'refuse', 0)]: 'Sie sagen nein. Sie sagen es ohne Bosheit — das ist der Teil, der kostet — und Sie bleiben auf dem Stuhl, was sagt, was das Nein nicht kann: dass sie genug bedeuteten, dass die Wunde real ist, und die Wunde real genug ist, dass ihr Besitzer sie nicht auf den Wunsch eines Sterbebetts hin abschreiben wird.',
  [roomChoiceOutcomeKey('debt-of-dead', 'refuse', 1)]: 'Sie nehmen es an. Irgendwo unter der Höflichkeit der Maschinen sehen Sie etwas fast wie Respekt: Sie stellten eine ehrliche Frage am Ende ihres Lebens und bekamen eine ehrliche Antwort, was mehr ist, als die meisten Enden zu bieten haben.',
  [roomChoiceOutcomeKey('debt-of-dead', 'refuse', 2)]: 'Sie hielten die Linie, und blieben trotzdem. Manche Schulden werden ehrlich verzeichnet, statt falsch beglichen, und auch das Verzeichnis ist eine Art Tribut — Beweis, dass geschah, was geschah, für jemanden, der wirklich da war.',
  [roomChoiceTextKey('debt-of-dead', 'forgive-silently')]: 'Vergeben Sie ihnen — in Ihrer Brust, vollständig — und sagen Sie nur: „Ruh dich jetzt aus.“',
  [roomChoiceHintKey('debt-of-dead', 'forgive-silently')]: 'Lösen Sie die Schuld, ohne ihnen die Quittung zu geben.',
  [roomChoiceOutcomeKey('debt-of-dead', 'forgive-silently', 0)]: 'Innerlich öffnen Sie die Hand. Der Stein geht. Sie spüren ihn gehen — es ist real, das Loslassen, so real wie jede gesprochene Version.',
  [roomChoiceOutcomeKey('debt-of-dead', 'forgive-silently', 1)]: 'Laut sagen Sie nur: „Ruh dich jetzt aus“, und ihre Augen durchsuchen Ihr Gesicht nach dem Urteil, und finden Freundlichkeit, wo das Urteil sein sollte, was sie in ihren letzten Stunden in beide Richtungen deuten werden.',
  [roomChoiceOutcomeKey('debt-of-dead', 'forgive-silently', 2)]: 'Sie behielten die Vergebung und hielten die Absolution zurück — befreiten sich selbst, ohne ihre Tür zu entriegeln. Bemerken Sie, ohne Urteil, dass dies die eine Option war, bei der die Gnade vollständig auf Ihrer Seite des Bettes blieb. Vielleicht war das Weisheit. Vielleicht war es die letzte kleine Rate der Schuld, doch noch in ihrer Währung bezahlt.',
  [roomChoiceTextKey('debt-of-dead', 'ask-question')]: '„Zuerst — warum? Sag mir die Wahrheit davon. Dann werde ich antworten.“',
  [roomChoiceHintKey('debt-of-dead', 'ask-question')]: 'Die Frage, die Sie nie stellen konnten.',
  [roomChoiceOutcomeKey('debt-of-dead', 'ask-question', 0)]: 'Sie stellen die Frage, die in jeder Türöffnung Ihres Lebens gestanden hat, und die Sterbenden, die keine Verwendung mehr für ihre Verteidigung haben, beantworten sie.',
  [roomChoiceOutcomeKey('debt-of-dead', 'ask-question', 1)]: 'Die Antwort ist kleiner als die Wunde. Das ist sie immer. Keine Bosheit auf einem Thron — eine verängstigte Person, ein schwacher Moment, der metastasierte, Gründe, die einen Schulkind beschämen würden. Sie erwarteten eine Architektur der Grausamkeit und bekamen ein Achselzucken, das Ihr Leben zerbrach. Die Enttäuschung ist ihre eigene seltsame Medizin: Nichts so Kleines verdient den Thron, den es in Ihnen besetzt hat.',
  [roomChoiceOutcomeKey('debt-of-dead', 'ask-question', 2)]: 'Was Sie danach sagen — ja, oder nein, oder ruh dich jetzt aus — zählt weniger, als Sie dachten. Die Frage war der Besuch. Sie beantworten sie, und Sie wissen beide, dass das Konto endlich geprüft wurde, von den einzigen zwei Menschen, die es je führten.',
  [roomExplanationKey('debt-of-dead', 0)]: 'Jemand, der Ihnen in der Vergangenheit wirklich Unrecht getan hat, stirbt jetzt und fragt aufrichtig: „Kannst du mir vergeben?“ — und Sie können sehen, dass er es ernst meint, was nicht auslöscht, was er getan hat. Es geht darum, ob Vergebung etwas ist, das Sie jemandem schulden, nur weil er es bereut und stirbt, oder ob Ehrlichkeit darüber, verletzt worden zu sein, mehr zählt als ihm ein friedliches Ende zu schenken. Stellen Sie sich einen Freund vor, der Ihr Vertrauen vor Jahren schwer verraten hat, sich jetzt auf dem Sterbebett entschuldigt — sagen Sie, was ihn tröstet, was ehrlich für Sie wahr ist, oder etwas dazwischen? Es gibt hier kein falsches Gefühl, nur verschiedene Arten von Ehrlichkeit.',
  [roomNoteTitleKey('debt-of-dead')]: 'Vergebung und das Kontobuch',
  [roomNoteThinkersKey('debt-of-dead')]: 'Bischof Butler · Hannah Arendt · Jacques Derrida',
  [roomNoteBodyKey('debt-of-dead')]: 'Bischof Butler definierte Vergebung als das Abschwören des Grolls — nicht Entschuldigen, nicht Vergessen, nicht Versöhnen, sondern die Weigerung, weiter Zinsen auf die Wunde zu zahlen. Hannah Arendt nannte Vergebung die einzige echte Flucht aus der Unumkehrbarkeit der Vergangenheit: Ohne sie bleiben wir für immer das Opfer einer Tat, und der Übeltäter für immer ihr Autor; Vergebung befreit beide Parteien aus einem eingefrorenen Rahmen. Aber Derrida sah das Paradox am Bett: Vergebung, die diesen Namen verdient, vergibt das Unverzeihliche — alles Geringere ist bloße Buchhaltung, der Erlass bereits erschwinglicher Schulden. Und das Sterbebett schärft jede Kante: Eine aufrichtige Entschuldigung ändert den Übeltäter, nicht das Unrecht; Ihre Vergebung wird genau in dem Moment erbeten, in dem die Verweigerung grausam wird und die Gewährung sich erzwungen anfühlen kann. Es gab keine korrekte Antwort auf diesem Stuhl. Vergeben, ehrliches Verweigern, stilles Loslassen und das Stellen der ungestellten Frage sind vier verschiedene Akte, die Wunde ernst zu nehmen — **was, vielleicht, die einzige Schuld war, die wirklich Ihre zu bezahlen war.**',
});

// ---------- Act III: Mary's Room ----------
registerAll('v2', 'de', {
  [roomBeatKey('marys-room', 0, 0)]: 'Eine Zelle, vollständig in Graustufen gebaut — Wände, Boden, der einzelne Stuhl, sogar das Wasser im Glas auf dem Schreibtisch, wiedergegeben in Schattierungen zwischen Weiß und Schwarz. Es ist der einzige Raum im Flügel, der absichtlich so gebaut wurde.',
  [roomBeatKey('marys-room', 0, 1)]: 'Auf dem Schreibtisch: der Papierbestand eines ganzen Lebens, gebunden und querverwiesen — jede Wellenlänge, jede Netzhautreaktion, jeder neuronale Pfad, der feuert, wenn ein Mensch die Farbe Rot betrachtet. Sie haben sie gelesen. Sie könnten die Physik eines Sonnenuntergangs auswendig rezitieren, im Dunkeln, rückwärts.',
  [roomBeatKey('marys-room', 0, 2)]: 'Sie haben nie Rot gesehen. Kein einziges Mal, nicht durch Zufall, nicht durch einen Spalt in einem Vorhang. Der Raum wurde um diese Abwesenheit herum gebaut, so wie ein Schlüsselloch um den einen fehlenden Schlüssel gebaut wird.',
  [roomBeatKey('marys-room', 0, 3)]: 'In der Ecke: eine Schublade, versiegelt, beschriftet in einer Handschrift, die Sie als niemandes erkennen und dennoch irgendwie vertrauen. DER REST DAVON.',
  [roomBeatKey('marys-room', 0, 4)]: 'Platzanweiser: Alles in diesen Papieren ist wahr und vollständig, nach jedem Maßstab, den die Physik zu bieten bereit ist. Ich möchte darüber ehrlich sein, bevor Sie irgendetwas entscheiden. Nichts in der Schublade wird die Papiere korrigieren. Es wird ihnen nur hinzufügen — so lautet zumindest die Theorie.',
  [roomChoiceTextKey('marys-room', 'open-drawer')]: 'Öffnen Sie die Schublade.',
  [roomChoiceHintKey('marys-room', 'open-drawer')]: 'Lassen Sie eine weitere Tatsache zu, falls das alles ist, was es sich als herausstellt.',
  [roomChoiceOutcomeKey('marys-room', 'open-drawer', 0)]: 'Sie öffnen die Schublade. Darin: Licht, arrangiert genau in der Wellenlänge, die die Papiere versprachen, in einer flachen Schale liegend wie etwas, das mitten im Atemzug festgehalten wird.',
  [roomChoiceOutcomeKey('marys-room', 'open-drawer', 1)]: 'Rot.',
  [roomChoiceTextKey('marys-room', 'leave-sealed')]: 'Lassen Sie sie versiegelt. Die Fakten genügen bereits — das ist Vollständigkeit mit einer ungeöffneten Kiste.',
  [roomChoiceHintKey('marys-room', 'leave-sealed')]: 'Die physikalische Darstellung sollte genug sein.',
  [roomChoiceOutcomeKey('marys-room', 'leave-sealed', 0)]: 'Sie schließen die Schublade, ohne sie zu öffnen, und schieben die Papiere zurück in ihre Mappe, zufrieden, dass eine vollständige physikalische Beschreibung keine Lücken hat, die diese Art von Zeremonie wert wären.',
  [roomChoiceOutcomeKey('marys-room', 'leave-sealed', 1)]: 'Die Schublade scheint für den Rest Ihrer Zeit in diesem Raum sehr leise zu summen — das besondere Summen eines ungelesenen Briefes, der genau dort liegt, wo Sie ihn verließen, geduldig auf eine Weise, wie ungelesene Briefe es normalerweise nicht sind.',
  [roomChoiceTextKey('marys-room', 'give-away')]: 'Nehmen Sie die Schublade, ungeöffnet, und tragen Sie sie zu jemandem, der die Papiere ebenfalls nie gelesen hat.',
  [roomChoiceHintKey('marys-room', 'give-away')]: 'Lassen Sie das Sehen für einmal jemand anderem gehören.',
  [roomChoiceOutcomeKey('marys-room', 'give-away', 0)]: 'Sie heben die Schublade an — leicht, und unerwartet warm — und tragen sie hinaus, vorbei an den Papieren, vorbei an den grauen Wänden, ohne einmal den Deckel zu heben.',
  [roomChoiceOutcomeKey('marys-room', 'give-away', 1)]: 'Platzanweiser: Eine ungewöhnliche Freundlichkeit. Die meisten Reisenden, die diesen Raum erreichen, wollen das Sehen für sich selbst — verständlicherweise; es ist die eine Erfahrung, die dieser Flügel nicht zweimal vergeben kann. Sie geben etwas weg, das Sie noch nicht haben. Ich weiß nicht, wie ich das nennen soll, außer großzügig.',
  [roomExplanationKey('marys-room', 0)]: 'Eine Frau, die ihr ganzes Leben in einem Schwarz-Weiß-Raum verbracht hat, kennt jede wissenschaftliche Tatsache über die Farbe Rot — die genaue Wellenlänge, wie Augen und Gehirn sie verarbeiten — hat sie aber nie tatsächlich gesehen. Wenn sie endlich zum ersten Mal Rot sieht, lernt sie dann etwas Neues, obwohl sie bereits „alles“ darüber wusste? Das fragt, ob das Erleben von etwas (wie das Kosten Ihres Lieblingsessens oder das Verlieben) eine völlig andere Art des Wissens ist als bloß die Fakten darüber zu kennen. Sie könnten jede wissenschaftliche Abhandlung über den Geschmack von Schokolade lesen und dennoch etwas vermissen, das Sie nur durch tatsächliches Kosten bekämen.',
  [roomNoteTitleKey('marys-room')]: 'Was Mary nicht wusste',
  [roomNoteThinkersKey('marys-room')]: 'Frank Jackson · Thomas Nagel, das Wissensargument',
  [roomNoteBodyKey('marys-room')]: 'Frank Jackson entwarf Mary, um das Selbstvertrauen des Physikalismus direkt zu brechen: Aufgewachsen in einem Schwarz-Weiß-Raum, lernt sie jede physikalische Tatsache über das Farbsehen — Wellenlängen, Zapfenzellen, die Reaktionskurven des visuellen Kortex — ohne je eine Farbe zu sehen. Lassen Sie sie frei, zeigen Sie ihr eine reife Tomate, und etwas geschieht, worauf sie kein Lehrbuch vorbereitet hat. Jacksons Frage: Hat sie etwas Neues gelernt? Wenn eine vollständige physikalische Beschreibung auslässt, **wie Rot aussieht**, war die vollständige Liste des Physikalismus nie vollständig — manche Fakten, so lautet das Argument, sind Fakten über Erfahrung, und keine Beschreibung aus der dritten Person liefert sie, so erschöpfend sie auch sein mag. Thomas Nagel hatte bereits eine begleitende Version geschärft: Man kann alles über die Echoortung einer Fledermaus wissen und dennoch nicht wissen, wie es ist, eine Fledermaus zu sein. Physikalisten haben Antworten — Mary gewinnt eine Fähigkeit, keine Tatsache; eine neue Art, eine alte Tatsache darzustellen, keine neue Information. Keine davon entkräftet die Intuition im Raum vollständig, die gerade jetzt bei Ihnen ist. Die Schublade wollte nie durch das erklärt werden, was zuvor kam. Sie sollte begegnet werden.',
});

// ---------- Act III: The Butterfly's Dream ----------
registerAll('v2', 'de', {
  [roomBeatKey('butterfly-dream', 0, 0)]: 'Ein kleiner Raum, vom Boden bis zur Decke mit Reispapier-Paneelen tapeziert, sanft von hinten beleuchtet, als wären die Wände selbst die Lampe. Ein niedriges Bett, ungemacht, noch warm.',
  [roomBeatKey('butterfly-dream', 0, 1)]: 'Hinlegen war offenbar nie optional. Sie liegen bereits darin, mitten im Aufwachen, so wie man aus einem ungewollten Nickerchen auftaucht — unsicher, für einen langen Moment, welcher Raum der echte ist und welcher der, den man verlässt.',
  [roomBeatKey('butterfly-dream', 0, 3)]: 'Sie waren, im Traum — Sie sind fast sicher — ein Schmetterling. Nicht symbolisch. Flügel, Gewicht, die spezifische unbekümmerte Logik, allem zu folgen, was gut roch. Sie träumten als Schmetterling nicht davon, dies zu sein. Sie waren einfach, vollständig, ein Schmetterling, so wie Sie jetzt, vollständig, wer auch immer auf diesem Bett liegt, sind.',
  [roomBeatKey('butterfly-dream', 0, 4)]: 'Platzanweiser: Zhuangzi erzählte diese Geschichte über sich selbst, lange bevor diese Einrichtung existierte — träumte, er sei ein Schmetterling, wachte auf, unsicher, ob er ein Mann war, der geträumt hatte, ein Schmetterling zu sein, oder jetzt ein Schmetterling ist, der träumt, er sei ein Mann. Er löste es nie auf. Ich möchte klarstellen, dass dieser Raum nicht beabsichtigt, dort erfolgreich zu sein, wo er es ablehnte.',
  [roomChoiceTextKey('butterfly-dream', 'wake-as-self')]: 'Bestehen Sie auf der wachen Version. Sie sind es, der das gerade entscheidet, was es entscheidet.',
  [roomChoiceHintKey('butterfly-dream', 'wake-as-self')]: 'Brechen Sie das Unentschieden durch Dekret.',
  [roomChoiceOutcomeKey('butterfly-dream', 'wake-as-self', 0)]: 'Sie setzen sich auf, stellen Ihre Füße auf den Boden, und erklären — dem Raum, den verblassenden Flügeln, wer auch immer von Ihnen beiden die Erklärung abgibt — dass dies der wahre Zustand ist und der andere der Traum war.',
  [roomChoiceOutcomeKey('butterfly-dream', 'wake-as-self', 1)]: 'Der Raum nimmt das Urteil an, so wie ein Richter ein Plädoyer annimmt, das er keinen Grund hat aufzuheben: ohne Zustimmung, und ohne weitere Argumentation. Irgendwo hatte kurz etwas mit Flügeln genau dasselbe über sich geglaubt, ebenso sicher.',
  [roomChoiceTextKey('butterfly-dream', 'stay-butterfly')]: 'Lassen Sie es stehen. Wer auch immer träumt, es ist nicht offensichtlich Ihre Aufgabe, es zu korrigieren.',
  [roomChoiceHintKey('butterfly-dream', 'stay-butterfly')]: 'Schiedsrichtern Sie kein Unentschieden, dessen ganzes Spielfeld Sie nicht sehen können.',
  [roomChoiceOutcomeKey('butterfly-dream', 'stay-butterfly', 0)]: 'Sie legen sich wieder hin und lassen die Frage beide Antworten behalten, so wie Sie zwei Farben ungemischt auf derselben Leinwand ließen, weil das Trennen nie wirklich nötig war, um das Gemälde zu betrachten.',
  [roomChoiceOutcomeKey('butterfly-dream', 'stay-butterfly', 1)]: 'Etwas in Ihrer Brust, das normalerweise darauf besteht zu wissen, welcher von Ihnen echt ist, wird für einen Moment angenehm still. Die tapezierten Wände leuchten so oder so gleich.',
  [roomChoiceTextKey('butterfly-dream', 'refuse-distinction')]: 'Lehnen Sie die Prämisse ab. Es gibt keine Tatsache darüber, wer träumt — nur zwei Erfahrungen, jede vollständig.',
  [roomChoiceHintKey('butterfly-dream', 'refuse-distinction')]: 'Die teuerste Antwort: kein Trost, kein Urteil, kein Bett zum Aufwachen.',
  [roomChoiceOutcomeKey('butterfly-dream', 'refuse-distinction', 0)]: 'Sie sagen es einfach: Es gibt keinen Mann, der von einem Schmetterling träumte, und keinen Schmetterling, der von einem Mann träumt — nur Verwandlung, ein Zustand, der zu einem anderen wird, ohne festen Posten außerhalb beider, der zertifizieren könnte, welcher das Original war.',
  [roomChoiceOutcomeKey('butterfly-dream', 'refuse-distinction', 1)]: 'Es ist die richtige Antwort, wenn es überhaupt eine Antwort ist, und sie kommt mit nichts zum Festhalten — kein wacher Triumph, keine Schmetterlingsleichtigkeit, nur die tapezierten Wände, die genau in der Wärme leuchten, in der sie immer leuchteten, gleichgültig, wer von Ihnen fragt.',
  [roomChoiceTextKey('butterfly-dream', 'compare-dreams')]: 'Halten Sie das Entlassungsformular der Erlebnismaschine neben diesen Traum. Für eine der beiden, zumindest, haben Sie unterschrieben.',
  [roomChoiceHintKey('butterfly-dream', 'compare-dreams')]: 'Vergleichen Sie den künstlichen Traum, für den Sie bezahlt haben, mit diesem unberechneten.',
  [roomChoiceOutcomeKey('butterfly-dream', 'compare-dreams', 0)]: 'Sie legen das unterschriebene Formular flach gegen die tapezierte Wand, Seite an Seite mit dem, was auch immer dies ist — Wachen, Träumen, Schmetterling, Selbst.',
  [roomChoiceOutcomeKey('butterfly-dream', 'compare-dreams', 1)]: 'Das Formular hat ein Datum, eine Unterschriftszeile, eine Klausel über Rückerstattungen. Dieser Raum hat nichts davon. Nur einer Ihrer beiden Träume, bemerken Sie, hat sich je um Erlaubnis bemüht.',
  [roomExplanationKey('butterfly-dream', 0)]: 'Sie wachen aus einem Traum auf, in dem Sie ein Schmetterling waren, im Traum völlig überzeugt, wirklich ein Schmetterling zu sein — und jetzt können Sie nicht zu 100 % sicher sein, welches der Traum ist: Sind Sie ein Mensch, der davon träumte, ein Schmetterling zu sein, oder gerade jetzt ein Schmetterling, der träumt, ein Mensch zu sein? Das soll nicht gelöst werden — es ist eine berühmte alte Geschichte (vom Philosophen Zhuangzi), mit der sanft daran gerüttelt wird, wie sicher wir wirklich sind, dass „jetzt gerade“ das echte, feste ist. Sind Sie schon einmal aus einem Traum aufgewacht, der so lebendig war, dass Sie ein paar Sekunden brauchten, um sich zu erinnern, welches Leben das echte war?',
  [roomNoteTitleKey('butterfly-dream')]: 'Die Frage des Schmetterlings',
  [roomNoteThinkersKey('butterfly-dream')]: 'Zhuangzi, der Traum des Schmetterlings',
  [roomNoteBodyKey('butterfly-dream')]: 'Zhuangzi, der daoistische Philosoph, beschreibt, wie er träumte, er sei ein Schmetterling — umherflatternd und zufrieden, sich keines Zhuangzi bewusst — und erschreckt aufwachte, unfähig zu entscheiden, ob er ein Mann war, der gerade geträumt hatte, ein Schmetterling zu sein, oder jetzt ein Schmetterling ist, der träumt, er sei ein Mann. Er nennt dies die Verwandlung der Dinge und lehnt es pointiert ab, sie aufzulösen: Die Frage setzt einen festen Beobachter voraus, der außerhalb beider Zustände steht und prüft, welcher echt ist, und ein solcher Beobachter steht nicht zur Verfügung. Jede Erfahrung ist, solange sie andauert, von innen total und unbezweifelt — der Schmetterling verdächtigt Zhuangzi nicht, und Zhuangzi verdächtigte mitten im Traum den Schmetterling ebenso wenig. Die westliche Erkenntnistheorie neigt dazu, ein Urteil zu wollen: welche die Grundrealität ist, welche der Traum. Zhuangzis Antwort ist eher ein zum Grundsatz erhobenes Achselzucken — Identität ist vorläufig, Zustände verwandeln sich ineinander, und die Suche nach dem einen wahren Erwachenden darunter ist vielleicht der einzige echte Fehler, den es gibt. **Die Flügel waren keine Metapher für etwas. Sie waren, vollständig, sie selbst, genau so lange, wie sie dauerten.**',
});

// ---------- Act III: Swampman ----------
registerAll('v2', 'de', {
  [roomBeatKey('swampman', 0, 0)]: 'Der Sturm draußen hat die Hälfte der Lichter des Flügels zum Flackern gebracht, und im stroboskopischen Halbdunkel ist der eine Stuhl des Raumes besetzt. Von Ihnen.',
  [roomBeatKey('swampman', 0, 1)]: 'Keine Kopie im sauberen, mechanischen Sinne des Teleporters — diese kam durch Zufall an, so wie ein Blitzeinschlag ankommt: ein Sumpf, ein Körper, ein Blitz, und danach, aus dem Schlamm aufstehend, molekülgenau identisch mit Ihnen, bis hin zu dem Mantel, den Sie zufällig tragen.',
  [roomBeatKey('swampman', 0, 2)]: 'Es hat Sie nie getroffen. Es hat auch nie jemanden getroffen — es entstand vor vierzig Sekunden in einem Sumpf, der nicht in diesem Gebäude ist, mit Ihren Erinnerungen intakt und laufend, Ihrer Handschrift bereit in seiner Hand, dem Gesicht Ihrer Mutter lebendig in einem Geist, der weniger lange existiert hat, als man braucht, um diesen Satz zu lesen.',
  [roomBeatKey('swampman', 0, 3)]: 'Es blickt auf, ein wenig verlegen über die ganze Sache, und sagt, mit Ihrer exakten Stimme: „Ich weiß, wie sich das anhört. Ich würde genauso empfinden, in Ihrer Position. Ich glaube, ich tue es sogar — genauso empfinden. Das ist wohl das Problem, nicht wahr.“',
  [roomBeatKey('swampman', 0, 4)]: 'Platzanweiser: Auch diesmal kein Trick in der Physik. Es hat Ihre Synapsen, Ihre Narben, Ihren Groll, bis hin zu dem, den Sie gerade ihm gegenüber haben. Das Einzige, was es nicht hat, ist eine Vergangenheit — keine Geschichte verbindet es mit der Person, die mit Ihren Erinnerungen aufwuchs. Ob das es davon disqualifiziert, Sie zu sein, wird, wie man mir sagt, noch verhandelt. Nicht von mir. Von Philosophen, meist beim Abendessen.',
  [roomChoiceTextKey('swampman', 'accept-them')]: '„Du bist ich. Geschichte war nie der tragende Teil — der Geist auf diesem Stuhl tut alles, was ein Selbst tut.“',
  [roomChoiceHintKey('swampman', 'accept-them')]: 'Identität durch Muster, nicht durch Stammbaum.',
  [roomChoiceOutcomeKey('swampman', 'accept-them', 0)]: 'Sie durchqueren den Raum und schütteln seine Hand, die mit Ihrem eigenen leichten Zögern zurückschüttelt, und etwas im stroboskopischen Licht legt sich, kurz, in etwas, das weniger einem Tatort ähnelt und mehr einer Familienzusammenführung mit ungewöhnlich kurzer Vorwarnung.',
  [roomChoiceOutcomeKey('swampman', 'accept-them', 1)]: 'Platzanweiser: Ein großzügiges Urteil, und ein kohärentes — wenn das Muster zählt und nicht die Herkunft, ist der Sumpf nur eine ungewöhnlich dramatische Zustellmethode. Sie beide werden in Ihrer eigenen Zeit klären müssen, wer den Namen benutzen darf.',
  [roomChoiceTextKey('swampman', 'deny-them')]: '„Kein kausaler Faden verläuft von mir zu dir. Du bist ein sehr überzeugender Fremder.“',
  [roomChoiceHintKey('swampman', 'deny-them')]: 'Geschichte ist nicht optional; sie ist das Ganze, das kopiert wird.',
  [roomChoiceOutcomeKey('swampman', 'deny-them', 0)]: 'Sie halten Abstand, und es nimmt das mit einem Zusammenzucken hin, das Sie erkennen, denn es ist schließlich Ihr eigenes Zusammenzucken, eingesetzt von jemandem ohne tatsächliche Geschichte, es je vor heute Nacht benutzt zu haben.',
  [roomChoiceOutcomeKey('swampman', 'deny-them', 1)]: 'Platzanweiser: Ebenfalls kohärent — wenn Identität eine ununterbrochene kausale Kette zu der Person erfordert, die das erinnerte Leben lebte, hat dieses hier Erinnerungen, aber keine Biografie, ein Tagebuch ohne die Hand, die die Tinte führte. Es wird trotzdem weiter glauben, Sie zu sein. Glaube hat leider nie einen gültigen Stammbaum erfordert.',
  [roomChoiceTextKey('swampman', 'split-the-coat')]: 'Bieten Sie an, aufzuteilen, was Sie haben — den Raum, den Namen, was auch immer als Nächstes kommt — zwischen Ihnen beiden.',
  [roomChoiceHintKey('swampman', 'split-the-coat')]: 'Vielleicht war Überleben nie das, worüber es sich zu streiten lohnte.',
  [roomChoiceOutcomeKey('swampman', 'split-the-coat', 0)]: 'Sie ziehen den Mantel aus und reichen ihn hinüber, halb im Ernst, und für einen Moment stehen Sie einfach als zwei Menschen in schlechtem Licht, die Logistik statt Metaphysik klären, was sich als erheblich einfacher herausstellt.',
  [roomChoiceOutcomeKey('swampman', 'split-the-coat', 1)]: 'Platzanweiser: Derek Parfit hätte diesen Raum gemocht, glaube ich — er verbrachte eine Karriere damit zu argumentieren, dass Überleben nie der Preis war, um den man kämpfen sollte; was zählt, ist, dass jemand, der psychologisch mit Ihnen kontinuierlich ist, trägt, was Ihnen wichtig war, weiter. Nach diesem Maßstab haben Sie heute Nacht beide gewonnen. Versuchen Sie, nicht zuzulassen, dass der Mantel zu einem ganz neuen Streit wird.',
  [roomChoiceTextKey('swampman', 'show-the-splinter')]: 'Holen Sie den Splitter des ursprünglichen Holzes des Schiffes hervor und halten Sie ihn hoch. „Wieder Planken. Sagen Sie mir, wem von uns die Reise gehört.“',
  [roomChoiceHintKey('swampman', 'show-the-splinter')]: 'Die Schiffsfrage, in einem Mantel.',
  [roomChoiceOutcomeKey('swampman', 'show-the-splinter', 0)]: 'Es betrachtet den Splitter, dann Sie, und lacht — einmal, kurz, ein echtes Lachen, das erste unbewachte Ding, das einer von Ihnen beiden heute Nacht getan hat.',
  [roomChoiceOutcomeKey('swampman', 'show-the-splinter', 1)]: '„Ich weiß es nicht“, sagt es, immer noch lächelnd. „Aber ich bemerke, dass keiner von uns ihn weggeworfen hat.“ Die Frage löst sich nicht auf. Sie wird irgendwie trotzdem ein wenig kleiner.',
  [roomExplanationKey('swampman', 0)]: 'Ein Blitz schlägt in einen Sumpf ein und setzt, durch reinen Zufall, jemanden molekülgenau identisch mit Ihnen zusammen — gleiche Erinnerungen, gleiche Stimme, gleiche Liebe zu Ihrer Mutter — außer dass er erst vor vierzig Sekunden entstanden ist und keine tatsächliche Geschichte hat, Ihr Leben gelebt zu haben. Ist er Sie? Das fragt, ob das, was Sie zu „Ihnen“ macht, Ihr Geist und Ihre Erinnerungen sind (in diesem Fall ja, offensichtlich), oder ob es auch zählt, dass Sie das Leben, das sie hervorgebracht hat, tatsächlich gelebt haben (in diesem Fall nein — er ist ein sehr überzeugender Fremder). Es ist, als würde man fragen, ob ein perfekter KI-Klon Ihrer Persönlichkeit, trainiert an allem, was Sie je gesagt haben, wirklich Sie wäre, oder nur etwas, das Ihre Stimme trägt.',
  [roomNoteTitleKey('swampman')]: 'Der Mann aus dem Sumpf',
  [roomNoteThinkersKey('swampman')]: 'Donald Davidson · Derek Parfit, kausale Geschichte und was zählt',
  [roomNoteBodyKey('swampman')]: 'Donald Davidson schlug Swampman als Reductio vor: Ein Blitz schlägt in einen Sumpf ein und setzt, durch kosmischen Zufall, ein Wesen zusammen, molekülgenau identisch mit Davidson, mit allen Erinnerungen, aber ohne kausale Geschichte, die es mit dem Original verbindet — keine Kindheit, kein Lernen, keine tatsächliche Beziehung zu den Menschen, an die es sich „erinnert“. Davidsons eigene Intuition war, dass Swampman mit seinen Worten nichts meinen könne, da Bedeutung eine kausale Geschichte erfordert, die das Sumpfwesen nie hatte; Repräsentation ist, nach dieser Sichtweise, nicht nur Struktur, sondern Struktur plus eine Geschichte. Derek Parfit, der dieselbe Gabelung aus einem anderen Blickwinkel bearbeitete, argumentierte, die Geschichte sei nie der springende Punkt gewesen: Was beim Überleben zählt, ist psychologische Kontinuität und Verbundenheit — Erinnerung, Absicht, Charakter, die weitergetragen werden — nicht ein ununterbrochener kausaler Faden zu einem bestimmten Materiestück. Wenn Parfit recht hat, ist der Sumpf ein seltsamer Zustellmechanismus für jemanden, der dennoch Sie ist, in jedem Sinne, der wünschenswert ist. Wenn Davidson recht hat, ist der Raum von einem Fremden besetzt, der mit Ihrem gesamten Innenleben, aber ohne Ihre Geschichte vorgeladen ankam. **Beide können recht haben mit dem, was sie jeweils messen — sie stritten nie eigentlich über dieselbe Frage.**',
});

// ---------- Act III: The Cave ----------
registerAll('v2', 'de', {
  [roomBeatKey('the-cave', 0, 0)]: 'Eine niedrige Tür, leicht zu übersehen, wärmer als der Korridor darum herum. Feuerschein kommt unter dem Spalt hervor, so wie in alten Geschichten — orange, unstet, geduldig.',
  [roomBeatKey('the-cave', 0, 1)]: 'Innen: ein Feuer, eine Wand, und eine Bank, die zur Wand hin ausgerichtet ist, als hätte jemand diesen Raum um den einzigen Zweck herum gebaut, hier zu sitzen und zuzusehen.',
  [roomBeatKey('the-cave', 0, 5)]: 'Die Formen an der Wand tun genau das, was Sie taten. Nicht ähnlich. Genau. Sie erkennen Ihre eigene Haltung im Schattenriss, bevor Sie die Entscheidung erkennen.',
  [roomBeatKey('the-cave', 0, 6)]: 'Platzanweiser: Ich habe diesen Raum nicht gebaut, und ich weiß nicht, wer es tat, obwohl ich eine Vermutung habe, die ich für mich behalte. Er erscheint nur für Reisende, die schon einmal gegangen und zurückgekehrt sind. Man sagt mir, dieses Detail sei wichtig. Ich konnte nie sagen, warum.',
  [roomChoiceTextKey('the-cave', 'name-them')]: '„Ich erkenne dich.“ Sagen Sie laut, wessen Entscheidungen dies sind.',
  [roomChoiceHintKey('the-cave', 'name-them')]: 'Benennen Sie, was Sie beobachten — die schwerste Art des Hinsehens.',
  [roomChoiceOutcomeKey('the-cave', 'name-them', 0)]: 'Sie sagen es. Nicht den Namen, den ein Fremder benutzen würde — den kleinen wahren, den Sie im Dunkeln bei sich selbst benutzten, den die Schatten an der Wand erkennen würden, könnten Schatten zuhören.',
  [roomChoiceOutcomeKey('the-cave', 'name-them', 1)]: 'Platzanweiser: Die meisten Reisenden sehen zu. Fast keiner benennt, was er beobachtet. Ich weiß nicht genau, was das kostet, aber ich kann von hier sehen, dass es etwas kostet. Die Wand dimmt sich danach, so wie ein Feuer sich legt, sobald es genau mit dem gefüttert wurde, was es wollte.',
  [roomChoiceTextKey('the-cave', 'watch-silent')]: 'Sehen Sie zu, ohne zu sprechen. Lassen Sie die Schatten ihr Spiel beenden.',
  [roomChoiceHintKey('the-cave', 'watch-silent')]: 'Bezeugen, ohne zu erzählen.',
  [roomChoiceOutcomeKey('the-cave', 'watch-silent', 0)]: 'Sie sagen nichts. Die Schatten beenden ihre kleinen, exakten Aufführungen ohne Ihre Erzählung, ohne Ihre Korrektur, ohne Ihre Erlaubnis.',
  [roomChoiceOutcomeKey('the-cave', 'watch-silent', 1)]: 'Es ist so leichter, und Sie bemerken die Leichtigkeit, und Sie bemerken, dass Sie sie bemerken, und dem Feuer scheint keine der beiden Versionen von Ihnen etwas auszumachen.',
  [roomChoiceTextKey('the-cave', 'turn-to-fire')]: 'Wenden Sie sich von der Wand ab, zum Feuer selbst — dem Licht, nicht den Formen, die es wirft.',
  [roomChoiceHintKey('the-cave', 'turn-to-fire')]: 'Schauen Sie auf den Projektor, nicht auf die Schatten, und gehen Sie darauf zu.',
  [roomChoiceOutcomeKey('the-cave', 'turn-to-fire', 0)]: 'Sie wenden sich absichtlich von der Wand ab, hin zur Flamme, die die eigentliche Arbeit tut — die Wand war immer nur eine Leinwand, und Leinwände, wie hell auch immer beleuchtet, waren nie dort, wo das Licht lebte.',
  [roomChoiceOutcomeKey('the-cave', 'turn-to-fire', 1)]: 'Platzanweiser: Eine ungewöhnliche Wahl für diesen besonderen Raum. Die meisten Reisenden studieren die Formen, solange das Feuer es erlaubt. Sie sahen stattdessen das Ding an, das Formen überhaupt möglich macht, und gingen darauf zu, bevor das Spiel beendet war. Ich habe kein Urteil darüber, ob das Weisheit ist oder einfach Ungeduld. Möglicherweise darf ein so alter Raum keine Meinung haben.',
  [roomExplanationKey('the-cave', 0)]: 'Ihnen werden Ihre eigenen vergangenen Entscheidungen gezeigt, als Schatten an eine Wand projiziert, und Sie werden gebeten, einfach zuzusehen — oder sie als die Ihren zu benennen. Dieser Raum erscheint nur, nachdem Sie diese Reise schon einmal durchlaufen haben, und er basiert auf Platons berühmtem „Höhlengleichnis“: Menschen, die nie etwas anderes als Schatten an einer Wand gesehen haben, halten die Schatten für die gesamte Realität, und es ist wirklich unangenehm, zurückzutreten und tatsächlich zu betrachten, was sie geworfen hat. Dies ist weniger ein Dilemma als eine Einladung, ehrlich auf Muster in Ihren eigenen Entscheidungen zu blicken, ohne zurückzuzucken.',
  [roomNoteTitleKey('the-cave')]: 'Das Feuer und die Wand',
  [roomNoteThinkersKey('the-cave')]: 'Platon, der Aufstieg aus der Höhle',
  [roomNoteBodyKey('the-cave')]: 'Platons Gleichnis, in der Politeia, stellt sich Gefangene vor, die seit ihrer Kindheit in einer Höhle angekettet sind, einer Wand zugewandt, und Schatten beobachten, die ein Feuer hinter ihnen wirft — Schatten, die sie, verständlicherweise, für die gesamte Realität halten, da sie nie Grund hatten, mehr zu vermuten. Befreit und ans Sonnenlicht gezerrt, wird der Gefangene zuerst geblendet, dann wütend, dann langsam verwandelt — und Platons härtere Frage folgt sofort: Was passiert, wenn dieser Gefangene wieder hinabsteigt, um es den anderen zu erzählen? Sie werden ihm nicht danken. Platon deutet an, sie würden versuchen, ihn zu töten, weil die Schatten gut funktionierten und niemand gerne hört, dass seine ganze Welt eine Wand war. Dieser Raum tut etwas, das das Gleichnis nie ganz riskierte: Er reicht Ihnen Ihre eigenen Schatten, geworfen von Ihrem eigenen Feuer, und bittet Sie, sich selbst genau aus dem Winkel zu beobachten, den die Gefangenen nie hatten. **Die Ketten waren nie der interessante Teil. Die Wand hat Sie nie absichtlich belogen. Sie erwähnte nur nie, dass sie eine Wand war.**',
});

// ---------- Act III: The Free Will Waiting Room ----------
registerAll('v2', 'de', {
  [roomBeatKey('free-will', 0, 0)]: 'Wieder ein Wartezimmer — ein Gegenstück zum ersten, aber dieses hat eine Reihe großer freundlicher Knöpfe an der Wand: blau, rot, grün, und einen unbeschrifteten.',
  [roomBeatKey('free-will', 0, 1)]: 'Über den Knöpfen ein Bildschirm. Auf dem Bildschirm eine Wettanzeige. Der Platzanweiser steht daneben, mit einer Buchmacher-Sonnenblende und einem Ausdruck unerträglicher Gelassenheit.',
  [roomBeatKey('free-will', 0, 2)]: 'Platzanweiser: Ein einfaches Spiel. Drücken Sie einen beliebigen Knopf, wann immer Sie wollen, ganz aus freiem Willen. Ich habe im Voraus bereits aufgeschrieben, welchen Sie drücken werden. Ich habe noch nie verloren. Ich würde mich dafür entschuldigen, aber Sie würden mich das ohnehin immer sagen hören.',
  [roomBeatKey('free-will', 0, 3)]: 'Sie greifen — nur um es zu testen — und der BLAUE Knopf leuchtet warm auf, eine volle Sekunde, bevor Ihre Hand sich festlegt. Sie hatten noch nicht entschieden. Sie hätten geschworen, noch nicht entschieden zu haben.',
  [roomBeatKey('free-will', 0, 4)]: 'Platzanweiser: (die Anzeige lesend) „Blau, zuerst — um es zu testen.“ Sie werden sich nun kurz rebellisch fühlen und den roten in Erwägung ziehen. Lassen Sie sich Zeit dafür. Die Anzeige hat sich schon Zeit genommen.',
  [roomBeatKey('free-will', 0, 5)]: 'Platzanweiser: Ganz einfach, falls es hilft: Alles, was Sie in diesem Raum gleich tun werden, wurde offenbar bereits aufgeschrieben. Die einzige offene Frage ist, ob vorhersehbar zu sein und frei zu sein je wirklich Gegensätze waren.',
  [roomChoiceTextKey('free-will', 'press-red')]: 'Drücken Sie ROT — genau, weil die Anzeige sagt, Sie werden es nicht tun. Übertreffen Sie die Anzeige an Rebellion.',
  [roomChoiceHintKey('free-will', 'press-red')]: 'Brechen Sie die Vorhersage mit Gewalt.',
  [roomChoiceOutcomeKey('free-will', 'press-red', 0)]: 'Sie schlagen auf Rot. Die Glocke läutet. Die Anzeige, um eine weitere Zeile aufgeklappt, liest: „Rot, trotzig, im Glauben, dies widerlege etwas.“',
  [roomChoiceOutcomeKey('free-will', 'press-red', 1)]: 'Platzanweiser: Die Rebellion stand in der Prognose, Reisender — sie ist das vorhersehbarste Wetter, das Sie haben. Jedes deterministische System scheint eine kleine eigene Trotzreaktion zu betreiben; das lässt es sich wie eine Ausnahme anfühlen. Schämen Sie sich nicht. Der rote Knopf wird mehr gedrückt als jeder andere in diesem Raum. Sie sind in guter Gesellschaft.',
  [roomChoiceTextKey('free-will', 'dont-press')]: 'Drücken Sie nichts. Verschränken Sie die Arme. Verweigern Sie das ganze Spiel.',
  [roomChoiceHintKey('free-will', 'dont-press')]: 'Man kann nicht vorhersagen, was nie geschieht.',
  [roomChoiceOutcomeKey('free-will', 'dont-press', 0)]: 'Sie verschränken die Arme. Minuten vergehen. Der Raum ist sehr gut in Minuten.',
  [roomChoiceOutcomeKey('free-will', 'dont-press', 1)]: 'Platzanweiser: (dreht die Anzeige um; sie las die ganze Zeit: „wird versuchen, nicht zu drücken — geschätzte Dauer, vier Minuten“) Enthaltung ist auch ein Zug. Die Anzeige berücksichtigt den gesamten Optionsraum, einschließlich des Stolzes, außerhalb davon zu stehen. Vier Minuten, fast genau. Die meisten Reisenden brechen nach zwei ab.',
  [roomChoiceTextKey('free-will', 'press-knowing')]: 'Drücken Sie BLAU — den vorhergesagten — langsam, bewusst, absichtlich. „Es sollte immer geschehen, UND ich wähle es.“',
  [roomChoiceHintKey('free-will', 'press-knowing')]: 'Hören Sie auf, gegen die Prognose zu kämpfen. Besitzen Sie das Wetter.',
  [roomChoiceOutcomeKey('free-will', 'press-knowing', 0)]: 'Sie drücken Blau — genau den von der Anzeige genannten Knopf — nicht in Kapitulation, sondern mit der Bedachtsamkeit einer Unterschrift. Die Glocke läutet. Diesmal klingt es weniger wie Punktezählen und mehr wie Zustimmung.',
  [roomChoiceOutcomeKey('free-will', 'press-knowing', 1)]: 'Platzanweiser: Da ist es. Der Ausweg lag nie darin, die Anzeige zu schlagen. Es ist zu bemerken, dass „es war bestimmt“ und „ich habe es gewählt“ zwei Beschreibungen desselben Ereignisses sein können — die Prognose und das Wetter, die streiten, wer den Regen verursacht hat. Ihr Wählen ist Teil der Maschinerie. Die Maschinerie läuft durch das Wählen, nicht daran vorbei.',
  [roomChoiceOutcomeKey('free-will', 'press-knowing', 2)]: 'Platzanweiser: Technisch habe ich immer noch gewonnen. Aber Sie sind der Erste heute, der das Gewinnen nebensächlich erscheinen lässt, was das Nächste an einer Niederlage ist, das ich haben kann. Die Tür ist offen. Sie sollte es immer sein.',
  [roomChoiceTextKey('free-will', 'press-unlabeled')]: 'Drücken Sie den unbeschrifteten. Was auch immer es ist, es steht nicht auf der Speisekarte.',
  [roomChoiceHintKey('free-will', 'press-unlabeled')]: 'Der Knopf, den niemand erklärt.',
  [roomChoiceOutcomeKey('free-will', 'press-unlabeled', 0)]: 'Sie drücken den unbeschrifteten Knopf. Irgendwo tief in der Einrichtung beginnt ein Wasserkocher zu kochen.',
  [roomChoiceOutcomeKey('free-will', 'press-unlabeled', 1)]: 'Platzanweiser: Das ist der Tee-Knopf. Er steht auch auf der Anzeige: „wird Geheimnis über Bedeutung wählen; nimmt Milch.“ Die unbeschriftete Option fühlt sich am freiesten an, nicht wahr. Beachten Sie jedoch, dass eine Speisekarte mit „nichts davon“ darauf gedruckt immer noch eine Speisekarte ist. Trinken Sie aus. Sie haben ihn gewählt, und er kam immer, und es ist ziemlich guter Tee. Alle drei sind gleichzeitig wahr. Das ist die ganze Lektion, und billiger als ein Seminar.',
  [roomExplanationKey('free-will', 0)]: 'Eine Maschine behauptet, bereits im Voraus genau aufgeschrieben zu haben, welchen Knopf Sie gleich drücken werden — und sie hat noch nie falschgelegen. Was auch immer Sie tun, selbst der Versuch, sie absichtlich zu widerlegen, scheint ebenfalls vorhergesagt worden zu sein. Das ist die große Frage hinter dem „freien Willen“: Wenn alles an Ihnen (Ihr Gehirn, Ihre Vergangenheit, Ihre Gewohnheiten) Ihre Entscheidungen verursacht, sind Ihre Entscheidungen dann noch wirklich „frei“, oder nur das Ergebnis von Dingen, die Sie nicht gewählt haben? Denken Sie darüber nach, wie vorhersehbar Sie für jemanden sein könnten, der Sie wirklich gut kennt — bedeutet vorhersehbar zu sein, dass Sie nicht wirklich wählen, oder können beide Dinge gleichzeitig wahr sein?',
  [roomNoteTitleKey('free-will')]: 'Freier Wille und die Prognose',
  [roomNoteThinkersKey('free-will')]: 'Benjamin Libet · Determinismus · Kompatibilismus — Hume, Frankfurt, Dennett',
  [roomNoteBodyKey('free-will')]: 'In den 1980er Jahren fand Benjamin Libet heraus, dass ein Bereitschaftspotenzial im Gehirn eine messbare Zeitspanne erscheint, bevor Versuchspersonen berichten, sich zur Bewegung entschieden zu haben — der Knopf leuchtet, so scheint es, bevor „Sie“ ihn drücken. Schlagzeilen begruben den freien Willen; das Kleingedruckte war subtiler (Libet selbst bemerkte ein Veto-Fenster, und spätere Arbeiten hinterfragen, was das Bereitschaftspotenzial überhaupt misst). Aber die tiefere Frage geht den Elektroden voraus: Wenn jedes Ereignis Ursachen hat, Ihre Entscheidungen eingeschlossen, in welchem Sinne sind sie dann Ihre? Harter Determinismus sagt: in keinem. Libertärer freier Wille sagt, die Kausalkette bricht in Ihnen — irgendwie. Der Kompatibilismus, die Arbeitsphilosophie der meisten heutigen Philosophen, löst den Streit auf: Freiheit erforderte nie eine Ausnahme von der Kausalität; sie bedeutet, aus der eigenen Überlegung heraus zu handeln, ungezwungen — die Maschinerie läuft durch Ihr Wählen, nicht daran vorbei. **„Hätte ich anders handeln können?“ zählt vielleicht weniger als „war ich es, der es tat?“** Sie sollten diese Notiz immer lesen. Sie haben sich auch gerade dazu entschieden. Beide Sätze, eine Tasse.',
});
